import{_ as a,o as i,c as o,aj as l}from"./chunks/framework.C18smN11.js";const u=JSON.parse('{"title":"插件介绍","description":"","frontmatter":{"title":"插件介绍"},"headers":[],"relativePath":"qiantao/index.md","filePath":"qiantao/index.md","lastUpdated":1792576248000}'),e={name:"qiantao/index.md"};function d(n,t,r,s,c,h){return i(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="klkhk-plugin-qiandao-1-12-2" tabindex="-1">[klkhk]plugin_qiandao_1.12.2 <a class="header-anchor" href="#klkhk-plugin-qiandao-1-12-2" aria-label="Permalink to &quot;[klkhk]plugin_qiandao_1.12.2&quot;">​</a></h1><p>[[META:qiantao]]</p><blockquote><p>jar 文件名是 <code>[klkhk]plugin_qiandao_1.12.2.jar</code>。插件内部名（<code>plugin.yml</code>）仍是 <code>QianDao</code>，所以配置目录是 <code>plugins/QianDao/</code>、控制台前缀是 <code>[QianDao]</code> —— 二者不一致是正常的，改配置时认目录就行。</p></blockquote><blockquote><p>一个 1.12.2 的签到插件。玩家点一下，奖励到手；管理员不用改代码，改 <code>config.yml</code> 就能调整整套奖励体系。</p></blockquote><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>大部分签到插件只做到「每天给个东西」。这个插件多做了一步：让玩家<strong>舍不得断签</strong>。</p><ul><li>断签有补签卡兜底，不至于一天没上线就前功尽弃</li><li>连续 7 / 14 / 30 天有额外奖励，全服广播，面子也是奖励</li><li>右侧实时排行榜，不用管理员天天喊「今天谁还没签到」</li><li>金币直接进 ZPoints / PlayerPoints / Vault，不用再养一套经济系统</li></ul><p>反过来也要说清楚它的边界：奖励全部通过<strong>控制台指令</strong>发放，所以能接任何物品、经济、点券插件；它不内置商店、不做每日任务，保持单一职责。这些需求交给别的插件，或者 <a href="/plugin-wiki/custom">定制</a>。</p><h2 id="功能一览" tabindex="-1">功能一览 <a class="header-anchor" href="#功能一览" aria-label="Permalink to &quot;功能一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>每日签到</td><td>每天一次，默认凌晨 4:00 刷新（时区、刷新时间可配置）</td></tr><tr><td>七日周期</td><td>第 1~7 天奖励逐天递增，第 7 天终极大奖，之后循环</td></tr><tr><td>连续奖励</td><td>连续 7 / 14 / 30 天额外奖励 + 全服广播，断签归零</td></tr><tr><td>补签卡</td><td>右键打开补签面板，可补最近 N 天漏签，补签后连续天数恢复</td></tr><tr><td>在线奖励</td><td>累计在线满设定时长自动发补签卡，每日有上限</td></tr><tr><td>签到排行</td><td>屏幕右侧实时计分板 + <code>/qd rank</code> 图形化排行榜</td></tr><tr><td>金币联动</td><td>ZPoints / PlayerPoints / Vault 三选一</td></tr><tr><td>视听反馈</td><td>签到标题、音效、粒子、今日槽位附魔发光，全部可开关</td></tr><tr><td>数据安全</td><td><code>data.yml</code> 定时异步保存，自动清理 60 天前的旧记录</td></tr></tbody></table><h2 id="界面长什么样" tabindex="-1">界面长什么样 <a class="header-anchor" href="#界面长什么样" aria-label="Permalink to &quot;界面长什么样&quot;">​</a></h2><p><strong>签到主面板（45 格）</strong></p><ul><li>第 5 格：玩家头颅，显示连续天数、累计次数、补签卡数量</li><li>第 20~26 格：七日奖励展示，今天能领的那格附魔发光</li><li>第 32 格：补签卡与当前持有数量</li><li>底部：补签漏签日期 / 签到排行榜 / 关闭</li></ul><p><strong>补签面板（27 格）</strong>：列出最近 N 天可补签的日期，点击后二次确认，确认才扣卡。防止手滑，也防止玩家误点。</p><p><strong>排行榜面板（45 格）</strong>：按连续天数排，同天数看累计次数。右侧计分板是同一套数据，每分钟刷新一次。</p><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><ul><li><a href="/plugin-wiki/qiantao/install">安装部署</a> — jar 放哪、什么时候重启、升级怎么不冲掉配置</li><li><a href="/plugin-wiki/qiantao/commands">指令与权限</a> — 玩家命令、管理命令、权限节点</li><li><a href="/plugin-wiki/qiantao/config">配置详解</a> — 每个配置项干什么、默认值是多少</li><li><a href="/plugin-wiki/qiantao/economy">经济联动</a> — 让签到发点券或金币</li><li><a href="/plugin-wiki/qiantao/faq">常见问题</a> — 金币没到账、排行榜不显示、补签没日期</li><li><a href="/plugin-wiki/qiantao/changelog">更新日志</a> — 这个版本改了什么</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>服务端：Spigot / Paper <strong>1.12.2</strong></li><li>Java：<strong>8</strong> 及以上</li><li>可选前置：Vault + 经济插件、PlayerPoints、ZPoints</li></ul><p>前置都是 softdepend：不装也能正常签到，只是对应金币奖励自动跳过，控制台会告诉你跳过了。</p><blockquote><p>这是 1.12.2 专用构建，材质和音效用的是 1.12.2 的命名。1.13+ 请走定制，别硬塞。</p></blockquote>',21)])])}const k=a(e,[["render",d]]);export{u as __pageData,k as default};
